schema.source:
"""JSON-Schema → a schema-valid argument instance, spread across a coverage surface.

The value engine behind the mock teacher (:func:`anvil.datagen.synth.mock_llm`),
T2 chain-arg sampling (:mod:`chains`), and T6 world-task instantiation
(:mod:`world.task`). Given a tool's ``args_schema`` it produces a concrete instance
that honors ``$ref`` / ``const`` / ``enum`` / ``default`` / bounds / formats /
``minLength``·``maxLength`` / nested objects + arrays, and a per-call coverage mode
spreads the batch across minimal (required only), typical (required + ~half the
optionals), and maximal (every optional) calls — so the trained model sees the full
combinatorial surface, not one shape. Pure schema→value: no LLM, no I/O, seeded by
the caller's ``rand.Generator`` so every draw is reproducible.
"""

from typing import TYPE_CHECKING

from unstd import rand


if TYPE_CHECKING:
    from collections.abc import Callable


def _resolve_ref(ref: str, root: dict[str, object]) -> dict[str, object]:
    """Resolve a local ``#/$defs/Name`` ref against the schema root."""
    node: object = root
    for part in ref.lstrip("#/").split("/"):
        if isinstance(node, dict):
            node = node.get(part, {})
    return node if isinstance(node, dict) else {}


_FORMAT_SAMPLES: dict[str, Callable[[rand.Generator], str]] = {
    "email": lambda rng: f"user{rng.randint(1, 99)}@example.com",
    "date-time": lambda rng: "2026-06-19T14:30:00Z",
    "date": lambda rng: "2026-06-19",
    "time": lambda rng: "14:30:00",
    "uri": lambda rng: f"https://example.com/{rng.randint(1, 999)}",
    "uuid": lambda rng: "00000000-0000-4000-8000-000000000000",
}


def _bounds(
    spec: dict[str, object], lo_d: float, hi_d: float, *, integer: bool
) -> tuple[float, float]:
    """Inclusive (lo, hi) honoring minimum/maximum + their exclusive variants."""
    step = 1 if integer else 1e-3
    lo = spec.get("minimum")
    if not (lo is None or isinstance(lo, (int, float))):
        message = "invalid lo data"
        raise TypeError(message)
    if lo is None and (ex := spec.get("exclusiveMinimum")) is not None:
        if not (isinstance(ex, (int, float))):
            message = "invalid ex data"
            raise TypeError(message)
        lo = ex + step
    hi = spec.get("maximum")
    if not (hi is None or isinstance(hi, (int, float))):
        message = "invalid hi data"
        raise TypeError(message)
    if hi is None and (ex := spec.get("exclusiveMaximum")) is not None:
        if not (isinstance(ex, (int, float))):
            message = "invalid ex data"
            raise TypeError(message)
        hi = ex - step
    lo = lo_d if lo is None else lo
    hi = hi_d if hi is None else hi
    return (lo, max(lo, hi))


def _sample_string(name: str, spec: dict[str, object], rng: rand.Generator) -> str:
    if isinstance(fmt := spec.get("format"), str) and fmt in _FORMAT_SAMPLES:
        return _FORMAT_SAMPLES[fmt](rng)
    if (pat_const := spec.get("const")) is not None:
        return str(pat_const)
    s = f"{name}_{rng.randint(1, 999)}"
    mn = spec.get("minLength")
    if not (mn is None or isinstance(mn, int)):
        message = "invalid mn data"
        raise TypeError(message)
    if mn and len(s) < mn:
        s += "x" * (mn - len(s))
    mx = spec.get("maxLength")
    if not (mx is None or isinstance(mx, int)):
        message = "invalid mx data"
        raise TypeError(message)
    if mx is not None and len(s) > mx:
        s = s[:mx]
    return s


def _sample_value(
    name: str, spec: dict[str, object], root: dict[str, object], rng: rand.Generator
) -> object:
    if "$ref" in spec:
        ref = spec["$ref"]
        if not (isinstance(ref, str)):
            message = "invalid ref data"
            raise TypeError(message)
        spec = _resolve_ref(ref, root)
    if "const" in spec:
        return spec["const"]
    if choices := spec.get("enum"):
        if not (isinstance(choices, list)):
            message = "invalid choices data"
            raise TypeError(message)
        return rng.choice(choices)
    if "default" in spec and rng.random() < 0.4:  # sometimes the default, sometimes an edge
        return spec["default"]
    t = spec.get("type")
    if isinstance(t, list):
        t = next((x for x in t if x != "null"), "string")
    if t == "integer":
        lo, hi = _bounds(spec, 1, 100, integer=True)
        return rng.choice([int(lo), int(hi), rng.randint(int(lo), int(hi))])
    if t == "number":
        lo, hi = _bounds(spec, 1.0, 100.0, integer=False)
        return round(rng.uniform(lo, hi), 2)
    if t == "boolean":
        return rng.choice([True, False])
    if t == "array":
        items = spec.get("items")
        if not isinstance(items, dict):
            items = {}
        mn = spec.get("minItems", 1) or 1
        if not (isinstance(mn, (str, int, float))):
            message = "invalid mn data"
            raise TypeError(message)
        n = max(int(mn), rng.randint(1, 3))
        if (mx := spec.get("maxItems")) is not None:
            if not (isinstance(mx, (str, int, float))):
                message = "invalid mx data"
                raise TypeError(message)
            n = min(n, int(mx))
        return [_sample_value(name, items, root, rng) for _ in range(max(n, 0))]
    if t == "object":
        return sample_valid_args(spec, rng, root=spec)
    return _sample_string(name, spec, rng)


def sample_valid_args(
    schema: dict[str, object],
    rng: rand.Generator | None = None,
    *,
    root: dict[str, object] | None = None,
) -> dict[str, object]:
    """A schema-valid argument instance with a varied required+optional mix.

    A per-call coverage mode spreads the batch across minimal (required only),
    typical (required + ~half the optionals), and maximal (every optional) calls
    so the trained model sees the full combinatorial surface, not just one shape.
    """
    rng = rng or rand.Generator(0, backend="stdlib")
    root = root or schema
    props = schema.get("properties") or {}
    if not (isinstance(props, dict)):
        message = "invalid props data"
        raise TypeError(message)
    raw_required = schema.get("required") or []
    if not (isinstance(raw_required, list)):
        message = "invalid raw_required data"
        raise TypeError(message)
    required = set(raw_required)
    mode = rng.random()  # <.34 minimal · <.8 typical · else maximal
    out: dict[str, object] = {}
    for name, spec in props.items():
        spec = spec if isinstance(spec, dict) else {}
        if name not in required:
            if mode < 0.34:
                continue
            if mode < 0.8 and rng.random() < 0.5:
                continue
        out[name] = _sample_value(name, spec, root, rng)
    return out

corpus_trim.source:
def _trim(examples: list[TrainExample], cap: int, rng: rand.Generator) -> list[TrainExample]:
    """Deterministically trim a track to its budget (shuffle then cut)."""
    if cap <= 0:
        return []
    if len(examples) <= cap:
        return examples
    shuffled = examples[:]
    rng.shuffle(shuffled)
    return shuffled[:cap]

