def _has_tool_call(ex: TrainExample) -> bool:
    return any(m.get("role") == "assistant" and m.get("tool_calls") for m in ex.messages)

def _trigger(ex: TrainExample) -> str:
    return next(
        (str(m.get("content", "")) for m in reversed(ex.messages) if m.get("role") == "user"),
        "",
    )

def _mask_seed(seed: int, ex: TrainExample) -> int:
    """A stable, nonzero per-example alias seed (so a rebuild aliases identically)."""
    digest = hashlib.blake2b(f"{seed}|{ex.tool_name}|{_trigger(ex)}".encode(), digest_size=6)
    return int.from_bytes(digest.digest(), "big") or 1

def apply_function_masking(train: Iterable[TrainExample], *, fraction: float, seed: int) -> int:
    """Mark a ``fraction`` of tool-bearing TRAIN examples for name masking.

    Sets ``mask_seed`` on the selected examples (the emitter does the aliasing).
    Selection is reproducible (seeded RNG over the deterministic train order); the
    per-example seed is hashed from the trigger so the same line always aliases the
    same way. Returns the count marked. ``fraction<=0`` is a no-op.
    """
    if fraction <= 0:
        return 0
    rng = rand.Generator(seed, backend="stdlib")
    marked = 0
    for ex in train:
        if ex.kind not in _MASKABLE or not _has_tool_call(ex):
            continue
        if rng.random() < fraction:
            ex.mask_seed = _mask_seed(seed, ex)
            marked += 1
    return marked

curiosity.source:
class _Rng:
    def __init__(self) -> None:
        self._stream = rand.Generator(backend="stdlib")

    def seed(self, n: int | None = None) -> None:
        self._stream.seed(n)

    def choice[T](self, seq: list[T] | tuple[T, ...]) -> T:
        if not seq:
            msg = "Cannot choose from an empty sequence"
            raise IndexError(msg)
        return self._stream.choice(seq)

    def choices[T](
        self,
        population: list[T],
        weights: list[float] | None = None,
        *,
        k: int = 1,
    ) -> list[T]:
        if not population:
            return []
        if weights is None:
            return [self.choice(population) for _ in range(k)]
        total = float(sum(weights))
        if total <= 0:
            return [self.choice(population) for _ in range(k)]
        out: list[T] = []
        for _ in range(k):
            r = self._stream.random() * total
            acc = 0.0
            pick = population[-1]
            for item, w in zip(population, weights, strict=True):
                acc += float(w)
                if r <= acc:
                    pick = item
                    break
            out.append(pick)
        return out
